const item = $input.first();
const raw = item.json.body ?? item.json.data ?? item.json;
let parsed = raw;
if (typeof raw === 'string') {
  try { parsed = JSON.parse(raw); } catch (e) { throw new Error('Webhook body is not valid JSON'); }
} else if (raw && typeof raw === 'object' && typeof raw.body === 'string') {
  try { parsed = JSON.parse(raw.body); } catch (e) { parsed = raw; }
}
return [{
  json: {
    'Submitted At': parsed.submitted_at || new Date().toISOString(),
    'Business Name': parsed.business_name || '',
    'Business Type': parsed.business_type || '',
    'Contact Name': parsed.contact_name || '',
    'Contact Email': parsed.contact_email || '',
    Phone: parsed.phone || '',
    'Service Area': parsed.service_area || '',
    'Core Services': parsed.core_services || '',
    Offer: parsed.offer || '',
    'Trust Points': parsed.trust_points || '',
    'Landing Page URL': parsed.landing_page_url || '',
    'Campaign Goal': parsed.campaign_goal || '',
    CTA: parsed.cta || '',
    Notes: parsed.notes || '',
    Status: parsed.status || 'submitted',
    Source: parsed.source || 'victorialeads.ca',
    business_name: parsed.business_name || '',
    business_type: parsed.business_type || '',
    contact_name: parsed.contact_name || '',
    contact_email: parsed.contact_email || '',
    phone: parsed.phone || '',
    service_area: parsed.service_area || '',
    core_services: parsed.core_services || '',
    offer: parsed.offer || '',
    landing_page_url: parsed.landing_page_url || '',
    campaign_goal: parsed.campaign_goal || '',
    cta: parsed.cta || '',
    notes: parsed.notes || '',
  },
}];
